// Extrae datos del formulario, valida archivo y detecta tipo
const formItem = $('Application Form').item;
const newItem = { json: {}, binary: {} };

if (formItem.json) {
  newItem.json = { ...formItem.json };
}

// Validar que se adjunto un CV
const cargarCV = formItem.binary?.Cargar_CV;
if (!cargarCV) {
  throw new Error('No se adjunto ningun archivo CV. La postulacion requiere un CV.');
}

newItem.binary.Cargar_CV = cargarCV;

// Detectar extension del archivo para ruteo
const filename = cargarCV.fileName || '';
const ext = filename.split('.').pop().toLowerCase();
newItem.json._fileExtension = ext;

return [newItem];

// Extractor de texto para archivos Word (.docx)
// DOCX = archivo ZIP que contiene word/document.xml con el texto
const zlib = require('zlib');

const items = $input.all();
const results = [];

for (let idx = 0; idx < items.length; idx++) {
  const buf = await this.helpers.getBinaryDataBuffer(idx, 'Cargar_CV');
  let text = '';
  let offset = 0;

  // Recorrer entradas del ZIP buscando word/document.xml
  while (offset < buf.length - 30) {
    if (buf.readUInt32LE(offset) !== 0x04034b50) {
      offset++;
      continue;
    }

    const compressionMethod = buf.readUInt16LE(offset + 8);
    const compressedSize = buf.readUInt32LE(offset + 18);
    const nameLength = buf.readUInt16LE(offset + 26);
    const extraLength = buf.readUInt16LE(offset + 28);
    const fileName = buf.toString('utf8', offset + 30, offset + 30 + nameLength);
    const dataStart = offset + 30 + nameLength + extraLength;

    if (fileName === 'word/document.xml' && compressedSize > 0) {
      const compressed = buf.slice(dataStart, dataStart + compressedSize);
      let xml;

      if (compressionMethod === 0) {
        xml = compressed.toString('utf8');
      } else if (compressionMethod === 8) {
        xml = zlib.inflateRawSync(compressed).toString('utf8');
      }

      if (xml) {
        text = xml
          .replace(/<w:tab\/>/gi, '\t')
          .replace(/<w:br[^>]*?\/?>/gi, '\n')
          .replace(/<\/w:p>/gi, '\n')
          .replace(/<[^>]+>/g, '')
          .replace(/&amp;/g, '&')
          .replace(/&lt;/g, '<')
          .replace(/&gt;/g, '>')
          .replace(/&quot;/g, '"')
          .replace(/&apos;/g, "'")
          .replace(/\n{3,}/g, '\n\n')
          .trim();
      }
      break;
    }

    offset = dataStart + compressedSize;
  }

  if (!text) {
    throw new Error(
      'No se pudo extraer texto del archivo. ' +
      'Si es un .doc antiguo (Word 97-2003), conviertalo a .docx o .pdf antes de subirlo.'
    );
  }

  results.push({ json: { text } });
}

return results;
